/// %c0 = arith.constant 0 : index
/// %c1 = arith.constant 1 : index
/// %1 = xegpu.create_nd_tdesc %0[%c0, %c0], [%h, %w], [%w, %c1]: ui64 -> TensorDesc<8x16xf32>
